UPDATE "3.0_components" c
SET specifications = s.specs || COALESCE(c.specifications, '{}'::jsonb)
FROM seed s
WHERE EXISTS (
  SELECT 1 FROM unnest(string_to_array(c.supplier_model, ' ')) AS tok
  WHERE regexp_replace(upper(tok), '[^A-Z0-9.]', '', 'g') = s.model_key
);
